window.blogDetail = {"blogId":1603628806,"blogType":0,"pubTime":"2020-10-25 20:26","sLastModifyTime":"2020-10-25 20:29","lastModifyTime":1603628952,"cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读《红楼梦》（番外）黛钗合一——黛玉的成长与宝钗的女性传统价值回归","commentNum":0,"effect1":66048,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"在“红学”史上，“黛钗合一”始终是一个引人热议的论题。所谓“黛钗合一”是指《红楼》中的一种文本现象，初见于第五回，作者写了十一首判词，除却黛钗二人合做一首判词外，其余十人都是单独对应唯一一首判词，另外，在这一回的最后警幻仙姑领宝玉去和她的乳妹，小名唤作“可卿”的仙子见面时，作者对她的神态有过这样一段描写：“其鲜艳妩媚，有似乎宝钗，风流袅娜，则又如黛玉。”无论从判词还是“可卿”这个“梦中仙子”的形象...","artype":1,"arUins":"","blogid":1603628806,"voteids":0,"pubtime":1603628952,"replynum":0,"category":"个人日记","effect":66048,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1603628806,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读《红楼梦》（番外）黛钗合一——黛玉的成长与宝钗的女性传统价值回归","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1603628806"}